"""CI drift check: every generated file in the plugin matches its source.

- agents/claude/*.md and agents/codex/*.toml (and the optional sales advisor) match roles/*.yaml
- every generated file carries the "Generated by solo-to-scale; edit <source>" header
- docs/handbook.md agrees with models.yaml and the governance.json template
"""
import subprocess
import sys
from pathlib import Path

PLUGIN = Path(__file__).resolve().parents[1] / "plugins" / "solo-to-scale"
errors = []
if subprocess.call([sys.executable, str(PLUGIN / "scripts" / "sync_agents.py"), "--check"]) != 0:
    errors.append("agent files drifted from roles/")
gen = list((PLUGIN / "agents").rglob("*.*")) + list((PLUGIN / "templates" / "agents-optional").rglob("*.*"))
gen += [p for p in (PLUGIN / "templates" / "tools").rglob("*.py") if "__pycache__" not in p.parts]
gen += list((PLUGIN / "templates" / ".github").rglob("*.yml")) + [PLUGIN / "templates" / ".claude" / "statusline.py"]
for p in gen:
    head = "\n".join(p.read_text(encoding="utf-8").splitlines()[:8])
    if "Generated by solo-to-scale; edit `" not in head:
        errors.append(f"{p.relative_to(PLUGIN).as_posix()}: missing the 'Generated by solo-to-scale; edit <source>' header")
if subprocess.call([sys.executable, str(PLUGIN / "scripts" / "check_handbook.py")]) != 0:
    errors.append("handbook disagrees with the templates")
print("\n".join(errors) or "drift: OK")
sys.exit(1 if errors else 0)
